B.Wx=new A.nG("Battery Degradation","Minimum voltage and capacity trend across flights","SELECT\n  flight_id,\n  start_time,\n  ROUND(min_voltage, 2) AS min_voltage_v,\n  min_bat_pct,\n  ROUND(\n    min_voltage - LAG(min_voltage) OVER (ORDER BY start_time NULLS LAST),\n    3\n  ) AS voltage_delta\nFROM flight_stats\nWHERE start_time IS NOT NULL\nORDER BY start_time NULLS LAST\n",1,"batteryDegradation")
B.Ww=new A.nG("Vibration Trend","Average vibration levels across flights (motor wear indicator)","SELECT\n  flight_id,\n  start_time,\n  ROUND(avg_vibe_x, 3) AS avg_vibe_x,\n  ROUND(avg_vibe_y, 3) AS avg_vibe_y,\n  ROUND(avg_vibe_z, 3) AS avg_vibe_z,\n  ROUND(max_vibe_z, 3) AS max_vibe_z,\n  total_clips\nFROM flight_stats\nORDER BY start_time\n",2,"vibrationTrend")
B.Wy=new A.nG("Altitude Records","Highest altitude achieved per flight","SELECT\n  flight_id,\n  start_time,\n  ROUND(max_alt_m, 1) AS max_alt_m,\n  ROUND(max_ias_ms, 1) AS max_ias_ms,\n  duration_min\nFROM flight_stats\nORDER BY max_alt_m DESC\nLIMIT 20\n",3,"altitudeRecords")
B.Wv=new A.nG("Flight Frequency","Number of flights per week","SELECT\n  STRFTIME('%Y-%W', start_time::TIMESTAMP) AS week,\n  COUNT(*) AS flights,\n  ROUND(SUM(duration_min), 1) AS total_minutes\nFROM flight_stats\nWHERE start_time IS NOT NULL\nGROUP BY week\nORDER BY week\n",4,"flightFrequency")
